import { packageVersion } from "../distribution.js";
import { defineCommand } from "./command.js";
import { resolveCommand } from "./dispatch.js";
import { CliUsageError } from "./errors.js";
import { jsonFlag } from "./flags.js";
import { commandHelp, groupHelp, helpIndexJson, helpJson, referenceHelp, rootHelp, } from "./help.js";
/**
 * `agent-sdk help [command...]`: the index, one command's help, or with `--json`
 * the same as data. `--all` widens the index to every command's full help.
 */
export function helpCommand(commands) {
    return defineCommand({
        name: "help",
        group: "other",
        summary: "Show the command index, or the help for one command.",
        args: [{ name: "command", description: "Command words, such as `deploy`.", variadic: true }],
        flags: {
            all: {
                type: "boolean",
                description: "Include every command's full help (large: prefer one command).",
            },
            ...jsonFlag,
        },
        effect: "read",
        examples: ["agent-sdk help deploy", "agent-sdk help deploy --json", "agent-sdk help --json"],
        async run({ values, positionals, io }) {
            const write = io.stdout;
            const all = commands();
            if (positionals.length === 0) {
                if (values.json === true) {
                    const table = values.all === true
                        ? helpJson(all, packageVersion())
                        : helpIndexJson(all, packageVersion());
                    await write(`${JSON.stringify(table, null, 2)}\n`);
                }
                else {
                    await write(values.all === true ? referenceHelp(all) : rootHelp(all));
                }
                return 0;
            }
            const resolved = resolveCommand(all, positionals);
            if (resolved === undefined || resolved.rest.length > 0) {
                const prefix = positionals.join(" ");
                const group = groupHelp(all, prefix);
                if (group === undefined) {
                    throw new CliUsageError(`unknown command ${JSON.stringify(prefix)}`);
                }
                const children = all.filter((spec) => spec.name.startsWith(`${prefix} `));
                await write(values.json === true
                    ? `${JSON.stringify(helpJson(children, packageVersion()), null, 2)}\n`
                    : group);
                return 0;
            }
            await write(values.json === true
                ? `${JSON.stringify(helpJson([resolved.spec], packageVersion()).commands[0], null, 2)}\n`
                : commandHelp(resolved.spec));
            return 0;
        },
    });
}
